    "+ Add Current Tab": "+ Aktuellen Tab hinzufügen",
    "<strong>Leef is a labor of love.</strong> We do not collect telemetry, we do not sell your data, and we do not make any money. We don't take donations. Enjoy using Leef exactly as it was intended: fast, private, and free.": "<strong>Leef ist ein Herzensprojekt.</strong> Wir erfassen keine Telemetrie, verkaufen keine Daten und erzielen keine Einnahmen. Wir nehmen keine Spenden an. Nutzen Sie Leef genau wie vorgesehen: schnell, privat und kostenlos.",
    "<strong>Privacy Note:</strong> This file is saved locally to your Downloads folder. We do not collect telemetry. Unless you manually upload this file to the <a href=\"https://forms.gle/upGc1dvPYaoBw4o96\" target=\"_blank\" style=\"color: var(--primary-color); text-decoration: none;\">bug report form</a> or email it to <strong>contact.qtech@proton.me</strong>, no data leaves your device.": "<strong>Datenschutz-Hinweis:</strong> Diese Datei wird lokal in Ihrem Downloads-Ordner gespeichert. Wir erfassen keine Telemetrie. Außer wenn Sie diese Datei manuell im <a href=\"https://forms.gle/upGc1dvPYaoBw4o96\" target=\"_blank\" style=\"color: var(--primary-color); text-decoration: none;\">Fehlerberichtsformular</a> hochladen oder an <strong>contact.qtech@proton.me</strong> senden, verlassen keine Daten Ihr Gerät.",
    "<strong>Privacy Note:</strong> This file is saved locally to your Downloads folder. We do not collect telemetry. Unless you manually upload this file to the <a href=&quot;https://forms.gle/upGc1dvPYaoBw4o96&quot; target=&quot;_blank&quot; style=&quot;color: var(--primary-color); text-decoration: none;&quot;>bug report form</a> or email it to <strong>contact.qtech@proton.me</strong>, no data leaves your device.": "<strong>Datenschutz-Hinweis:</strong> Diese Datei wird lokal in Ihrem Downloads-Ordner gespeichert. Wir erfassen keine Telemetrie. Außer wenn Sie diese Datei manuell im <a href=&quot;https://forms.gle/upGc1dvPYaoBw4o96&quot; target=&quot;_blank&quot; style=&quot;color: var(--primary-color); text-decoration: none;&quot;>Fehlerberichtsformular</a> hochladen oder an <strong>contact.qtech@proton.me</strong> senden, verlassen keine Daten Ihr Gerät.",
    "A live look at how Leef is protecting your privacy.": "Ein Live-Blick darauf, wie Leef Ihre Privatsphäre schützt.",
