    "Error": "Fehler",
    "Even though they have stated that they respect GPC signals, this website may still use your data internally for analytics, data retention, internal research, and more. Read the privacy policy of this site for more info.": "Obwohl angegeben wurde, dass GPC-Signale respektiert werden, verwendet diese Website Ihre Daten möglicherweise intern für Analysen. Details in der Datenschutzerklärung.",
