    "GPC Signal": "GPC-Signal",
    "GPC Signal Disabled": "GPC-Signal deaktiviert",
    "GPC is a legal browser signal that automatically tells websites you want to opt-out of having your personal data sold or shared. Under laws like California's CCPA and Europe's GDPR, participating websites are legally required to respect this signal.": "GPC ist ein gesetzliches Browsersignal, das Websites automatisch mitteilt, dass Sie dem Verkauf oder der Weitergabe Ihrer persönlichen Daten widersprechen. Nach Gesetzen wie dem kalifornischen CCPA und der europäischen DSGVO sind teilnehmende Websites rechtlich verpflichtet, dieses Signal zu respektieren.",
    "Generate Diagnostics Log": "Diagnoseprotokoll erstellen",
    "Generate a local log file with system info to help us debug issues.": "Lokale Protokolldatei mit Systeminformationen zur Fehlerbehebung erstellen.",
    "Generated AI Output / CC-BY-4.0": "Generierte KI-Ausgabe / CC-BY-4.0",
    "Global Privacy Control": "Global Privacy Control",
    "Global Privacy Control (GPC)": "Global Privacy Control (GPC)",
    "Global Privacy Control (GPC) is unsupported on this website.": "Global Privacy Control (GPC) wird auf dieser Website nicht unterstützt.",
    "Got It": "Verstanden",
    "Great news! Leef successfully verified this site's GPC compliance declaration. The site officially respects the GPC signal.": "Großartige Neuigkeiten! Leef hat die GPC-Erklärung dieser Website erfolgreich verifiziert. Die Website respektiert das Signal offiziell.",
    "HTTPS Connections": "HTTPS-Verbindungen",
    "HTTPS-only mode": "Nur-HTTPS-Modus",
    "Heads Up:": "Hinweis:",
    "Hide headlines containing specific words or phrases. Not case-sensitive.": "Schlagzeilen mit bestimmten Wörtern oder Phrasen ausblenden. Groß-/Kleinschreibung egal.",
    "Homepage": "Startseite",
    "How to enable it:": "So aktivieren Sie es:",
    "However, there is no hard evidence that they strictly comply, or they may not legally have to comply depending on where the company is based.": "Es gibt jedoch keine Nachweise für eine strikte Einhaltung, oder das Unternehmen unterliegt je nach Sitz keinem solchen Gesetz.",
    "Ignore your explicit request to opt-out of personal data collection.": "Ihre ausdrückliche Aufforderung zur Deaktivierung der Datenerfassung ignorieren.",
    "Infrastructure": "Infrastruktur",
    "Interface Translations": "Oberflächenübersetzungen",
    "Interface text and browser options will use this spelling.": "Oberflächentexte und Optionen verwenden diese Schreibweise.",
    "Internet Disconnected": "Internetverbindung getrennt",
    "It has been audited by Leef and is confirmed to comply with the GPC standards.": "Wurde von Leef geprüft und entspricht nachweislich den GPC-Standards.",
    "Its privacy policy states that they comply with GPC.": "Die Datenschutzerklärung besagt, dass GPC eingehalten wird.",
    "Keep Leef secure and up to date by checking for updates on startup.": "Halten Sie Leef sicher und aktuell, indem beim Start nach Updates gesucht wird.",
    "LEEF VERSION": "LEEF-VERSION",
