    "Learn More": "Mehr erfahren",
    "Leef <span class=\"leef-version-val\"></span><br>Stable": "Leef <span class=\"leef-version-val\"></span><br>Stabil",
    "Leef <span class=&quot;leef-version-val&quot;></span><br>Stable": "Leef <span class=&quot;leef-version-val&quot;></span><br>Stabil",
    "Leef Browser Credits": "Leef Browser Mitwirkende",
    "Leef Browser is dedicated to the public domain under the <strong>CC0 1.0</strong> license. You are free to copy, modify, and distribute this software for any purpose without restriction.": "Leef Browser ist unter der <strong>CC0 1.0</strong>-Lizenz gemeinfrei gewidmet. Sie können diese Software ohne Einschränkung kopieren, ändern und verbreiten.",
    "Leef Browser | Changelog": "Leef Browser | Änderungsprotokoll",
    "Leef Browser | Credits": "Leef Browser | Mitwirkende",
    "Leef Browser | Settings": "Leef Browser | Einstellungen",
    "Leef Labs Privacy Analytics is built to give you transparency. Everything shown here is stored 100% locally on your machine.": "Leef Labs Datenschutz-Analysen bieten Ihnen volle Transparenz. Alles hier wird zu 100% lokal auf Ihrem Gerät gespeichert.",
    "Leef Software Updates": "Leef-Software-Updates",
    "Leef Version": "Leef-Version",
    "Leef has transmitted your Global Privacy Control preference to this site. We are currently checking the site's official compliance declaration (<code>/.well-known/gpc.json</code>) to verify if they respect the signal.": "Leef hat Ihr GPC-Signal übermittelt. Wir prüfen die Erklärung der Website (<code>/.well-known/gpc.json</code>), um zu bestätigen, ob sie das Signal respektiert.",
    "Leef is a fast, lightweight, and privacy-focused web browser built with Electron.<br>Designed for clarity, efficiency, and full local user control.": "Leef ist ein schneller, schlanker und datenschutzorientierter Webbrowser, entwickelt mit Electron.<br>Entworfen für Übersicht, Effizienz und volle lokale Kontrolle.",
    "Leef is built for you. We don't collect telemetry, make money, or take donations. All statistics and browsing data are kept locally on your machine.": "Leef wurde für Sie entwickelt. Wir erfassen keine Telemetrie, verdienen kein Geld und nehmen keine Spenden. Alle Daten bleiben lokal auf Ihrem Gerät.",
    "Leef sent the GPC signal to this site, but the site did not respond with a valid compliance document (<code>/.well-known/gpc.json</code>). It is highly likely the site does not recognize or support the GPC signal.": "Leef hat das GPC-Signal gesendet, aber die Website antwortete nicht mit einem gültigen Dokument. Es ist sehr wahrscheinlich, dass das Signal nicht unterstützt wird.",
    "Let's set up your personal, secure browsing experience in just a few quick steps.": "Richten Sie Ihr persönliches, sicheres Surferlebnis in wenigen Schritten ein.",
    "License & Policy": "Lizenz & Richtlinien",
