    "Since the site does not declare GPC compliance, it may continue to collect, share, or sell your personal information, search history, and browser settings without respect to your opt-out preference.": "Da die Website die Einhaltung nicht bestätigt, sammelt oder verkauft sie möglicherweise weiterhin Ihre Daten.",
