    "Technology Stack": "Technologie-Stack",
    "Thank you for choosing Leef.": "Vielen Dank, dass Sie sich für Leef entschieden haben.",
    "They are known to comply with GPC but don't have a header installed.": "Es ist bekannt, dass GPC respektiert wird, aber es ist kein technischer Header installiert.",
    "Third-Party Licenses & Attributions": "Lizenzen von Drittanbietern & Danksagungen",
    "This is an internal browser page. Leef does not broadcast tracking or privacy signals on internal offline pages.": "Dies ist eine interne Browser-Seite. Leef sendet keine Signale auf internen Seiten.",
    "This site is able to use your data even when you have the GPC header using a legal gray area. For example, AI chatbots can still see and use your chat info even when you have the GPC header. Read the site privacy policy for more info.": "Diese Website kann Ihre Daten unter rechtlichen Grauzonen nutzen (z. B. KI-Chatbots). Weitere Infos in der Datenschutzerklärung.",
    "This site is owned by an outside investor (e.g., Tencent, Blackrock, Amazon, Google, Microsoft) which may not follow the same privacy rules as this company. Read the site privacy policy for more info.": "Diese Website gehört einem externen Investor. Weitere Infos in der Datenschutzerklärung.",
    "This site says they support GPC, but some elements or sub-services on the site may not support it.": "Diese Website gibt an, GPC zu unterstützen, aber bestimmte Elemente oder Subdienste unterstützen es eventuell nicht.",
    "This site states they support GPC, but some parts of this company require you to download something to your computer (e.g., software, launchers) which are not audited by Leef.": "Einige Teile dieses Angebots erfordern Downloads, die nicht von Leef geprüft werden.",
    "This website ({domain}) does not recognize or support the GPC signal, or has been manually identified as non-compliant. It is on a blacklist of sites that actively ignore browser privacy signals.": "Diese Website ({domain}) erkennt das GPC-Signal nicht an oder ignoriert aktiv Datenschutz-Signale.",
    "This website ({domain}) has been manually checked and added to the Leef GPC trustlist. Even though it might not host a standard technical declaration (<code>/.well-known/gpc.json</code>), it is officially verified to respect privacy signals and user opt-out options.": "Diese Website ({domain}) wurde manuell geprüft und zur Vertrauensliste hinzugefügt. Sie respektiert nachweislich Datenschutzsignale.",
    "This website has been technically audited by Leef and is confirmed to comply with the GPC standards.": "Wurde von Leef technisch geprüft und entspricht nachweislich den GPC-Standards.",
    "This website has stated publicly, or in private correspondence with the Leef team or journalists, that it respects the GPC signal.": "Hat öffentlich oder gegenüber Journalisten bestätigt, dass das GPC-Signal respektiert wird.",
    "This website is part of a verified network of privacy-first domains.": "Diese Website gehört zu einem verifizierten Netzwerk datenschutzorientierter Domains.",
    "This website technically has GPC compliance because": "Diese Website erfüllt GPC technisch, weil",
    "This website utilizes a known privacy-respecting framework that honors GPC globally.": "Verwendet ein Framework, das GPC weltweit anerkennt.",
    "This website was manually verified because of one of these reasons:": "Diese Website wurde aus einem der folgenden Gründe manuell verifiziert:",
    "This website's privacy policy states that it will respect GPC as an opt-out request.": "Die Datenschutzerklärung besagt, dass GPC als Widerspruchsanfrage respektiert wird.",
    "To automatically tell websites not to sell or share your data, go to the Privacy & Security settings page and turn on the Global Privacy Control (GPC) toggle.": "Um Websites automatisch zu untersagen, Daten zu verkaufen, aktivieren Sie GPC in Datenschutz & Sicherheit.",
    "To comply with open-source and Creative Commons attribution requirements, we proudly acknowledge the following third-party materials used in Leef Browser:": "Um den Anforderungen von Open-Source und Creative Commons zu genügen, führen wir hier die verwendeten Komponenten auf:",
    "To see how well Leef protects you from ads and trackers, you first need to enable the blocker in your settings.": "Aktivieren Sie den Werbeblocker in den Einstellungen, um den Schutz vor Werbung zu sehen.",
    "Toggle advanced features to tailor your experience.": "Erweiterte Funktionen anpassen.",
    "Track your visits across other websites using tracking scripts and tracking cookies.": "Ihre Besuche über Websites hinweg mit Skripten und Tracking-Cookies verfolgen.",
    "Tracking Protection": "Tracking-Schutz",
    "Translations": "Übersetzungen",
    "Transparency & Funding": "Transparenz & Finanzierung",
    "Transparency Note:": "Transparenz-Hinweis:",
    "Treat your visit as an active opt-out request under privacy regulations (like GDPR and CCPA).": "Ihren Besuch als Widerspruch unter Datenschutzgesetzen (wie DSGVO) behandeln.",
