    "View on GitHub": "Auf GitHub ansehen",
    "We believe your data belongs to you. Leef Browser does not collect analytics, telemetry, or browsing history. Everything stays local on your machine.": "Wir glauben, dass Ihre Daten Ihnen gehören. Leef Browser erfasst keine Analysen, Telemetrie oder Browserverläufe. Alles bleibt lokal.",
