    "Diagnostics log generated! This file contains your settings and system info, but NO history or passwords. \n\nWould you like to open the bug report form now to upload it?": "Diagnoseprotokoll erstellt! Diese Datei enthält Ihre Einstellungen und Systemdaten, aber KEINEN Verlauf oder Passwörter. \n\nMöchten Sie das Fehlerberichtsformular jetzt öffnen, um es hochzuladen?",
    "Generating a bug report will save a diagnostics file to your PC.\n\nThis file contains system specs and configurations to help with bug reports. It will NEVER leave your PC unless you manually choose to share it.\n\nDo you want to proceed and generate the Bug Report log?": "Beim Erstellen eines Fehlerberichts wird eine Diagnosedatei auf Ihrem PC gespeichert.\n\nDiese Datei enthält Systemspezifikationen und Konfigurationen zur Fehlersuche. Sie verlässt NIEMALS Ihren PC, es sei denn, Sie teilen sie manuell.\n\nMöchten Sie fortfahren und das Fehlerprotokoll erstellen?",
    "Enter the origin URL (e.g., https://discord.com):": "Geben Sie die Website-URL ein (z.B. https://discord.com):",
