    "🔄 Refreshing News": "🔄 Nachrichten werden aktualisiert",
    "Leef is now your default browser for http and https links.": "Leef ist jetzt Ihr Standardbrowser für http- und https-Links.",
    "You are running the latest version of Leef.": "Sie verwenden die neueste Version von Leef.",
    "Could not reach the update server. Try again later.": "Update-Server konnte nicht erreicht werden. Versuchen Sie es später erneut.",
    "The update will download in the background.": "Das Update wird im Hintergrund heruntergeladen.",
    "The update has been downloaded and is ready to install.": "Das Update wurde heruntergeladen und ist bereit zur Installation.",
    "Individual feature-flags are coming soon in future updates as part of our advanced auditing suite.": "Einzelne Feature-Flags folgen in zukünftigen Updates als Teil unserer erweiterten Prüfungssuite.",
    "Your preferences have been applied.": "Ihre Einstellungen wurden übernommen.",
    "Internal Leef pages cannot be bookmarked.": "Interne Leef-Seiten können nicht als Lesezeichen gespeichert werden.",
    "This page is already in your bookmarks.": "Diese Seite befindet sich bereits in Ihren Lesezeichen.",
    "Please enter both a name and URL.": "Bitte geben Sie sowohl einen Namen als auch eine URL ein.",
    "You've seen all available stories. Try refreshing later!": "Sie haben alle verfügbaren Berichte gesehen. Versuchen Sie später zu aktualisieren!",
    "You are currently in Critical Mode. Please update Leef Browser to resume normal browsing.": "Sie befinden sich im kritischen Modus. Bitte aktualisieren Sie Leef Browser, um normal weiterzusurfen.",
    "Page failed to load. Would you like to check for a version on the Wayback Machine?": "Seite konnte nicht geladen werden. Möchten Sie in der Wayback Machine nach einer archivierten Version suchen?",
    "This tab is locked in Critical Mode.": "Dieser Tab ist im kritischen Modus gesperrt.",
