    "Manual GPC Verifications Disclaimer": "Manual GPC Verifications Disclaimer",
    "Please note that the manual GPC verification statuses in Leef Browser can be incorrect and will change with time. Not everything will always be up to date. Do not take the quick check we provide as a final say; corporations change their policies frequently, and a site that was non-compliant one month might be compliant the next. As the list grows, it becomes harder to manually check each and every site. Always check the privacy policy of the site itself. Our GPC status indicator is not to be seen as a definitive legal ruling on whether a company is operating legally or not.": "Please note that the manual GPC verification statuses in Leef Browser can be incorrect and will change with time. Not everything will always be up to date. Do not take the quick check we provide as a final say; corporations change their policies frequently, and a site that was non-compliant one month might be compliant the next. As the list grows, it becomes harder to manually check each and every site. Always check the privacy policy of the site itself. Our GPC status indicator is not to be seen as a definitive legal ruling on whether a company is operating legally or not.",
