    "This is an internal browser page. Leef does not broadcast tracking or privacy signals on internal offline pages.": "This is an internal browser page. Leef does not broadcast tracking or privacy signals on internal offline pages.",
    "This site is able to use your data even when you have the GPC header using a legal gray area. For example, AI chatbots can still see and use your chat info even when you have the GPC header. Read the site privacy policy for more info.": "This site is able to use your data even when you have the GPC header using a legal gray area. For example, AI chatbots can still see and use your chat info even when you have the GPC header. Read the site privacy policy for more info.",
    "While this website states they support GPC, their compliance is geographically limited to certain regions or states and may not be honored globally. Please review their privacy policy for details.": "While this website states they support GPC, their compliance is geographically limited to certain regions or states and may not be honored globally. Please review their privacy policy for details.",
    "This website is owned by an organization with a history of meeting only the bare minimum regulatory requirements for user privacy. We recommend exercising caution when sharing sensitive data.": "This website is owned by an organization with a history of meeting only the bare minimum regulatory requirements for user privacy. We recommend exercising caution when sharing sensitive data.",
    "This site is operated by a parent company that restricts GPC compliance to specific regions or states. Your privacy signal may not be respected depending on your location.": "This site is operated by a parent company that restricts GPC compliance to specific regions or states. Your privacy signal may not be respected depending on your location.",
    "This website requires identity verification through a third-party vendor. This vendor may operate under different privacy standards and could potentially sell your information to outside entities.": "This website requires identity verification through a third-party vendor. This vendor may operate under different privacy standards and could potentially sell your information to outside entities.",
    "This organization publicly supports the DNT (Do Not Track) header but has not made explicit statements regarding their support for the Global Privacy Control (GPC) signal.": "This organization publicly supports the DNT (Do Not Track) header but has not made explicit statements regarding their support for the Global Privacy Control (GPC) signal.",
    "If you explicitly opt-in to data sharing or selling on this website, those settings will override your browser's GPC preferences, and your signal will not be respected.": "If you explicitly opt-in to data sharing or selling on this website, those settings will override your browser's GPC preferences, and your signal will not be respected.",
    "This site is owned by an outside investor (e.g., Tencent, Blackrock, Amazon, Google, Microsoft) which may not follow the same privacy rules as this company. Read the site privacy policy for more info.": "This site is owned by an outside investor (e.g., Tencent, Blackrock, Amazon, Google, Microsoft) which may not follow the same privacy rules as this company. Read the site privacy policy for more info.",
    "This site says they support GPC, but some elements or sub-services on the site may not support it.": "This site says they support GPC, but some elements or sub-services on the site may not support it.",
    "This site states they support GPC, but some parts of this company require you to download something to your computer (e.g., software, launchers) which are not audited by Leef.": "This site states they support GPC, but some parts of this company require you to download something to your computer (e.g., software, launchers) which are not audited by Leef.",
    "This website ({domain}) does not recognize or support the GPC signal, or has been manually identified as non-compliant. It is on a blacklist of sites that actively ignore browser privacy signals.": "This website ({domain}) does not recognize or support the GPC signal, or has been manually identified as non-compliant. It is on a blacklist of sites that actively ignore browser privacy signals.",
    "This website ({domain}) has been manually checked and added to the Leef GPC trustlist. Even though it might not host a standard technical declaration (<code>/.well-known/gpc.json</code>), it is officially verified to respect privacy signals and user opt-out options.": "This website ({domain}) has been manually checked and added to the Leef GPC trustlist. Even though it might not host a standard technical declaration (<code>/.well-known/gpc.json</code>), it is officially verified to respect privacy signals and user opt-out options.",
    "This website has been technically audited by Leef and is confirmed to comply with the GPC standards.": "This website has been technically audited by Leef and is confirmed to comply with the GPC standards.",
    "This website has stated publicly, or in private correspondence with the Leef team or journalists, that it respects the GPC signal.": "This website has stated publicly, or in private correspondence with the Leef team or journalists, that it respects the GPC signal.",
    "This website is part of a verified network of privacy-first domains.": "This website is part of a verified network of privacy-first domains.",
    "This website technically has GPC compliance because": "This website technically has GPC compliance because",
    "This website utilizes a known privacy-respecting framework that honors GPC globally.": "This website utilizes a known privacy-respecting framework that honors GPC globally.",
