    "Google recently removed its built-in dictionary card and replaced it with AI answers. Because Leef blocks AI-generated content by default, you would have no way to look up word definitions.": "Google recently removed its built-in dictionary card and replaced it with AI answers. Because Leef blocks AI-generated content by default, you would have no way to look up word definitions.",
