    "news_disclaimer_tooltip": "News feeds and ESPN are not associated with Leef. We use direct public feeds to fetch headlines and scores locally. Your reading habits and topic preferences are stored 100% on your device and are never sent to news providers or Leef. All trademarks are the property of their respective owners.",
    "Leef Browser uses direct public RSS feeds (such as BBC, Yahoo, or custom feeds). Unlike other browsers that track what you read, Leef fetches news directly from servers to your machine with no middleman.": "Leef Browser uses direct public RSS feeds (such as BBC, Yahoo, or custom feeds). Unlike other browsers that track what you read, Leef fetches news directly from servers to your machine with no middleman.",
    "100% On-Device Smart Tuning:": "100% On-Device Smart Tuning:",
    "When you like, dislike, or dismiss content, topic weights are stored and computed exclusively inside your local browser. Preferences NEVER leave your device and are never sent to news providers or Leef.": "When you like, dislike, or dismiss content, topic weights are stored and computed exclusively inside your local browser. Preferences NEVER leave your device and are never sent to news providers or Leef.",
    "Content Preferences:": "Content Preferences:",
    "When you dismiss or tune a headline, that preference is stored exclusively in your local browser settings. We do not send this feedback to news providers or any server.": "When you dismiss or tune a headline, that preference is stored exclusively in your local browser settings. We do not send this feedback to news providers or any server.",
    "Live scores are fetched directly from ESPN's public APIs. All sports league names, team names, logos, and trademarks (including FIFA®, NFL®, NBA®, MLB®, NHL®) are registered trademarks of their respective owners. Their use on Leef Browser is solely for informational purposes to identify matches and does not imply any affiliation, sponsorship, or endorsement.": "Live scores are fetched directly from ESPN's public APIs. All sports league names, team names, logos, and trademarks (including FIFA®, NFL®, NBA®, MLB®, NHL®) are registered trademarks of their respective owners. Their use on Leef Browser is solely for informational purposes to identify matches and does not imply any affiliation, sponsorship, or endorsement.",
    "Because you are fetching RSS feeds and scores directly, providers may see your IP address and basic browser info. If you click on an article, you are leaving Leef's local environment, where their standard privacy policies apply.": "Because you are fetching RSS feeds and scores directly, providers may see your IP address and basic browser info. If you click on an article, you are leaving Leef's local environment, where their standard privacy policies apply.",
    "Leef Browser is an independent project and is not affiliated with, sponsored by, or endorsed by BBC, Yahoo, ESPN, FIFA®, or any other third-party trademark owners.": "Leef Browser is an independent project and is not affiliated with, sponsored by, or endorsed by BBC, Yahoo, ESPN, FIFA®, or any other third-party trademark owners.",
    "Manage websites that have requested access to your camera, microphone, or location.": "Manage websites that have requested access to your camera, microphone, or location.",
