    "GPC is a legal browser signal that automatically tells websites you want to opt-out of having your personal data sold or shared. Under laws like California's CCPA and Europe's GDPR, participating websites are legally required to respect this signal.": "GPC es una señal legal del navegador que indica automáticamente a los sitios que desea excluirse de la venta o divulgación de sus datos personales. Bajo leyes como la CCPA y el RGPD, los sitios participantes están legalmente obligados a respetar esta señal.",
