    "Great news! Leef successfully verified this site's GPC compliance declaration. The site officially respects the GPC signal.": "¡Excelentes noticias! Leef verificó con éxito la declaración de conformidad de GPC de este sitio. El sitio respeta oficialmente la señal GPC.",
