    "Treat your visit as an active opt-out request under privacy regulations (like GDPR and CCPA).": "Tratar su visita como una solicitud de exclusión voluntaria activa según las regulaciones de privacidad (como GDPR y CCPA).",
    "Typography & UI": "Tipografía e interfaz",
