    "Generate Diagnostics Log": "Generar registro de diagnóstico",
    "<strong>Privacy Note:</strong> This file is saved locally to your Downloads folder. We do not collect telemetry. Unless you manually upload this file to the <a href=\"https://forms.gle/upGc1dvPYaoBw4o96\" target=\"_blank\" style=\"color: var(--primary-color); text-decoration: none;\">bug report form</a> or email it to <strong>contact.qtech@proton.me</strong>, no data leaves your device.": "<strong>Nota de privacidad:</strong> Este archivo se guarda localmente en su carpeta de Descargas. No recopilamos telemetría. A menos que suba manualmente este archivo al <a href=\"https://forms.gle/upGc1dvPYaoBw4o96\" target=\"_blank\" style=\"color: var(--primary-color); text-decoration: none;\">formulario de informe de errores</a> o lo envíe por correo electrónico a <strong>contact.qtech@proton.me</strong>, ningún dato saldrá de su dispositivo.",
