    "⚠️ FACTORY RESET: This will clear all settings, labs, history, and bookmarks. The browser will then relaunch. Proceed?": "⚠️ RESTABLECIMIENTO DE FÁBRICA: Esto borrará todos los ajustes, labs, historial y marcadores. El navegador se reiniciará. ¿Continuar?",
    "Diagnostics log generated! This file contains your settings and system info, but NO history or passwords. \n\nWould you like to open the bug report form now to upload it?": "¡Registro de diagnóstico generado! Este archivo contiene su configuración e información del sistema, pero NINGÚN historial ni contraseñas. \n\n¿Desea abrir el formulario de reporte de errores para subirlo?",
    "Generating a bug report will save a diagnostics file to your PC.\n\nThis file contains system specs and configurations to help with bug reports. It will NEVER leave your PC unless you manually choose to share it.\n\nDo you want to proceed and generate the Bug Report log?": "Generar un informe de errores guardará un archivo de diagnóstico en su PC.\n\nEste archivo contiene especificaciones y configuraciones del sistema. NUNCA saldrá de su PC a menos que decida compartirlo manualmente.\n\n¿Desea continuar y generar el registro de errores?",
