    "The update has been downloaded and is ready to install.": "La actualización se ha descargado y está lista para instalarse.",
    "Individual feature-flags are coming soon in future updates as part of our advanced auditing suite.": "Las funciones individuales estarán disponibles en futuras actualizaciones en nuestra suite avanzada de auditoría.",
