    "No trackers detected yet.": "No se han detectado rastreadores aún.",
    "Streaming above 1440p on YouTube may slow down Leef. For the best experience, keep quality at 1440p or below.": "La reproducción a más de 1440p en YouTube puede ralentizar Leef. Para obtener la mejor experiencia, mantén la calidad en 1440p o menos.",
    "Google recently removed its built-in dictionary card and replaced it with AI answers. Because Leef blocks AI-generated content by default, you would have no way to look up word definitions.": "Google eliminó recientemente su tarjeta de diccionario integrada y la reemplazó por respuestas de IA. Como Leef bloquea el contenido de IA por defecto, no tendrías forma de buscar definiciones.",
    "You can turn this off any time in Leef &rarr; Settings &rarr; Browsing.": "Puedes desactivar esto en cualquier momento en Leef &rarr; Configuración &rarr; Navegación.",
    "Search Engine Safe Mode": "Modo seguro del motor de búsqueda",
    "Google recently changed its search engine backend to prioritize its \"AI Overview\" features. Because Leef injects specialized filters to strip out these AI components, the complex scripts served by Google can conflict with our blocker, causing the underlying Chromium layout engine to crash.": "Google modificó recientemente su motor para priorizar las descripciones generales de IA. Como Leef filtra estos componentes, los scripts de Google pueden entrar en conflicto y bloquear el motor Chromium.",
    "To keep your browsing seamless and avoid infinite crash loops, Leef automatically loads your query in Safe Mode using DuckDuckGo.": "Para que tu navegación sea fluida y evitar bucles de bloqueo, Leef carga automáticamente tu consulta en modo seguro con DuckDuckGo.",
    "Detected Signal": "Señal detectada",
    "Category": "Categoría",
    "AI models are trained on professional human data. High-quality human writing (academic, corporate, or journalistic) often flags as \"synthetic\" because it follows similar patterns of clarity and structure.": "Los modelos de IA están entrenados con datos humanos profesionales. La escritura de alta calidad a menudo se marca como \"sintética\" porque sigue patrones similares de claridad y estructura.",
    "Confidence: {level}": "Confianza: {level}",
