    "Open AppData": "Abrir AppData",
    "Report Bug": "Informar de un error",
    "Resets your settings, appearance, and bookmarks to defaults.": "Restablece tu configuración, apariencia y marcadores a los valores predeterminados.",
    "NUCLEAR OPTION: Clears EVERYTHING (Cache, Cookies, Sessions). Use only if nothing else works.": "OPCIÓN EXTREMA: Borra TODO (caché, cookies, sesiones). Usar solo si nada más funciona.",
    "Resets the window size and centers it on your main monitor.": "Restablece el tamaño de la ventana y la centra en la pantalla principal.",
    "Opens the local data folder where Leef stores its files.": "Abre la carpeta de datos local donde Leef almacena sus archivos.",
    "Generate a diagnostic log and report this issue to the Leef team.": "Generar un registro de diagnóstico e informar de este problema al equipo de Leef.",
    "Continue to Browser": "Continuar al navegador",
    "Save Diagnostic Log": "Guardar registro de diagnóstico",
    "Show in Folder": "Mostrar en la carpeta",
