    "+ Add Current Tab": "+ Ajouter l'onglet actif",
    "<strong>Leef is a labor of love.</strong> We do not collect telemetry, we do not sell your data, and we do not make any money. We don't take donations. Enjoy using Leef exactly as it was intended: fast, private, and free.": "<strong>Leef est un travail fait avec amour.</strong> Nous ne collectons pas de télémétrie, nous ne vendons pas vos données et nous ne gagnons pas d'argent. Nous n'acceptons pas de dons. Profitez de Leef exactement comme il a été conçu : rapide, privé et gratuit.",
    "Ad & Tracker Blocking": "Blocage des publicités et des traceurs",
    "Ad-Blocking Engine": "Moteur de blocage des publicités",
    "Ads & Trackers Blocked": "Publicités & traceurs bloqués",
    "Advanced": "Avancé",
    "Aggressively hibernate tabs to stay under a specific memory footprint.": "Mettre agressivement les onglets en veille prolongée pour rester sous une empreinte mémoire spécifique.",
