    "Automatically upgrade all connections to secure HTTPS": "Mettre automatiquement à niveau toutes les connexions vers HTTPS sécurisé",
    "Background activity limits": "Limites d'activité en arrière-plan",
    "Basic": "De base",
    "Block Google AI Overview": "Bloquer l'aperçu de l'IA de Google",
    "Bookmarks": "Favoris",
    "Bug Report": "Signaler un bug",
    "Build a detailed digital profile of your personal interests to target you with ads.": "Créer un profil numérique détaillé de vos intérêts personnels pour vous cibler avec des publicités.",
    "Change": "Modifier",
    "Check for Updates Now": "Vérifier les mises à jour maintenant",
    "Check GitHub on startup (External Call)": "Vérifier GitHub au démarrage (appel externe)",
