    "Efficiency Mode": "Mode efficacité",
    "Enable the volume booster in Quick Settings. Uses 0% CPU when set to 100%.": "Activer l'amplificateur de volume dans les réglages rapides. Utilise 0 % du processeur lorsqu'il est réglé sur 100 %.",
    "Even though they have stated that they respect GPC signals, this website may still use your data internally for analytics, data retention, internal research, and more. Read the privacy policy of this site for more info.": "Même s'ils ont déclaré respecter les signaux GPC, ce site Web peut toujours utiliser vos données en interne pour des analyses, la conservation des données, des recherches internes, etc. Lisez la politique de confidentialité de ce site pour plus d'informations.",
    "Fetch real-time search suggestions from Google as you type in the address bar": "Récupérer des suggestions de recherche Google en temps réel lors de la saisie dans la barre d'adresse",
    "Font Size": "Taille de la police",
    "French and Spanish interface translations generated and optimized by Google Gemini.": "Traductions de l'interface en français et en espagnol générées et optimisées par Google Gemini.",
    "General": "Général",
    "Generated AI Output / CC-BY-4.0": "Sortie d'IA générée / CC-BY-4.0",
    "Global Privacy Control": "Contrôle global de la confidentialité",
