    "Global Privacy Control (GPC) is unsupported on this website.": "Le contrôle global de la confidentialité (GPC) n'est pas pris en charge sur ce site Web.",
    "Good Afternoon": "Bon après-midi",
    "Good Evening": "Bonsoir",
    "Good Morning": "Bonjour",
    "Good Night": "Bonne nuit",
    "Got It": "Compris",
    "GPC is a legal browser signal that automatically tells websites you want to opt-out of having your personal data sold or shared. Under laws like California's CCPA and Europe's GDPR, participating websites are legally required to respect this signal.": "Le GPC est un signal de navigateur légal qui indique automatiquement aux sites que vous refusez la vente ou le partage de vos données personnelles. En vertu de lois telles que le CCPA et le RGPD, les sites participants sont légalement tenus de respecter ce signal.",
    "GPC Signal": "Signal GPC",
    "GPC Signal Disabled": "Signal GPC désactivé",
    "Great news! Leef successfully verified this site's GPC compliance declaration. The site officially respects the GPC signal.": "Excellente nouvelle ! Leef a vérifié avec succès la déclaration de conformité GPC de ce site. Le site respecte officiellement le signal GPC.",
