    "Leef Browser Credits": "Crédits de Leef Browser",
    "Leef Browser is dedicated to the public domain under the <strong>CC0 1.0</strong> license. You are free to copy, modify, and distribute this software for any purpose without restriction.": "Leef Browser est dédié au domaine public sous la licence <strong>CC0 1.0</strong>. Vous êtes libre de copier, modifier et distribuer ce logiciel à toutes fins et sans restriction.",
    "Leef has transmitted your Global Privacy Control preference to this site. We are currently checking the site's official compliance declaration (<code>/.well-known/gpc.json</code>) to verify if they respect the signal.": "Leef a transmis votre préférence Global Privacy Control à ce site. Nous vérifions actuellement la déclaration de conformité officielle du site (<code>/.well-known/gpc.json</code>) pour vérifier s'il respecte le signal.",
    "Leef sent the GPC signal to this site, but the site did not respond with a valid compliance document (<code>/.well-known/gpc.json</code>). It is highly likely the site does not recognize or support the GPC signal.": "Leef a envoyé le signal GPC à ce site, mais le site n'a pas répondu avec un document de conformité valide (<code>/.well-known/gpc.json</code>). Il est fort probable que le site ne reconnaisse pas ou ne prenne pas en charge le signal GPC.",
