    "Search or enter web address": "Rechercher ou saisir une adresse web",
    "Select your regional spelling for the browser interface.": "Sélectionnez votre orthographe régionale pour l'interface du navigateur.",
    "Sell or share your browsing habits, location, and device details with advertising networks and data brokers.": "Vendre ou partager vos habitudes de navigation, votre position et les détails de votre appareil avec des réseaux publicitaires et des courtiers en données.",
    "Sent": "Envoyé",
    "Services": "Services",
    "Settings": "Paramètres",
    "Signal Sent (Verifying)": "Signal envoyé (vérification)",
    "Since the site does not declare GPC compliance, it may continue to collect, share, or sell your personal information, search history, and browser settings without respect to your opt-out preference.": "Comme le site ne déclare pas sa conformité au GPC, il peut continuer à collecter, partager ou vendre vos informations personnelles, votre historique de recherche et les paramètres du navigateur sans respecter votre préférence d'exclusion.",
    "Site Permissions": "Autorisations du site",
    "Standard": "Standard",
    "Startup behavior": "Comportement au démarrage",
    "Stay up to date with the latest security fixes and features.": "Restez à jour avec les derniers correctifs de sécurité et fonctionnalités.",
    "Stop news from loading automatically. News only fetches when you click \"Refresh\".": "Empêcher le chargement automatique des actualités. Celles-ci ne sont récupérées que lorsque vous cliquez sur « Actualiser ».",
    "Strict": "Stricte",
    "Strip tracking pixels embedded in CSS": "Supprimer les pixels de suivi intégrés dans le CSS",
    "Suspend inactive tabs to save memory after 5 minutes.": "Suspendre les onglets inactifs pour économiser la mémoire après 5 minutes.",
    "Tab Volume": "Volume de l'onglet",
    "Troubleshooter": "Dépannage",
    "Technology Stack": "Technologies utilisées",
    "They are known to comply with GPC but don't have a header installed.": "Ils sont connus pour se conformer au GPC mais n'ont pas d'en-tête installé.",
    "Third-Party Licenses & Attributions": "Licences tierces & Attributions",
    "This is an internal browser page. Leef does not broadcast tracking or privacy signals on internal offline pages.": "Il s'agit d'une page interne du navigateur. Leef ne diffuse pas de signaux de suivi ou de confidentialité sur les pages hors ligne internes.",
    "This site is able to use your data even when you have the GPC header using a legal gray area. For example, AI chatbots can still see and use your chat info even when you have the GPC header. Read the site privacy policy for more info.": "Ce site est en mesure d'utiliser vos données même lorsque vous disposez de l'en-tête GPC en utilisant une zone d'ombre juridique. Par exemple, les chatbots d'IA peuvent toujours voir et utiliser vos informations de chat même lorsque vous disposez de l'en-tête GPC. Lisez la politique de confidentialité du site pour plus d'informations.",
    "This site is owned by an outside investor (e.g., Tencent, Blackrock, Amazon, Google, Microsoft) which may not follow the same privacy rules as this company. Read the site privacy policy for more info.": "Ce site appartient à un investisseur externe (par exemple, Tencent, Blackrock, Amazon, Google, Microsoft) qui peut ne pas suivre les mêmes règles de confidentialité que cette entreprise. Lisez la politique de confidentialité du site pour plus d'informations.",
    "This site says they support GPC, but some elements or sub-services on the site may not support it.": "Ce site indique qu'il prend en charge le GPC, mais certains éléments ou sous-services sur le site peuvent ne pas le prendre en charge.",
    "This site states they support GPC, but some parts of this company require you to download something to your computer (e.g., software, launchers) which are not audited by Leef.": "Ce site déclare prendre en charge le GPC, mais certaines parties de cette entreprise nécessitent de télécharger quelque chose sur votre ordinateur (par exemple, des logiciels, des lanceurs) qui ne sont pas audités par Leef.",
    "This website ({domain}) does not recognize or support the GPC signal, or has been manually identified as non-compliant. It is on a blacklist of sites that actively ignore browser privacy signals.": "Ce site Web ({domain}) ne reconnaît pas et ne prend pas en charge le signal GPC, ou a été identifié manuellement comme non conforme. Il figure sur une liste noire de sites qui ignorent activement les signaux de confidentialité du navigateur.",
    "This website ({domain}) has been manually checked and added to the Leef GPC trustlist. Even though it might not host a standard technical declaration (<code>/.well-known/gpc.json</code>), it is officially verified to respect privacy signals and user opt-out options.": "Ce site Web ({domain}) a été vérifié manuellement et ajouté à la liste de confiance GPC de Leef. Même s'il n'héberge pas de déclaration technique standard (<code>/.well-known/gpc.json</code>), il est officiellement vérifié pour respecter les signaux de confidentialité et les options d'opt-out des utilisateurs.",
    "This website has been technically audited by Leef and is confirmed to comply with the GPC standards.": "Ce site Web a été audité techniquement par Leef et sa conformité aux normes GPC est confirmée.",
    "This website has stated publicly, or in private correspondence with the Leef team or journalists, that it respects the GPC signal.": "Ce site Web a déclaré publiquement, ou dans une correspondance privée avec l'équipe Leef ou des journalistes, qu'il respecte le signal GPC.",
    "This website is part of a verified network of privacy-first domains.": "Ce site Web fait partie d'un réseau vérifié de domaines respectueux de la vie privée.",
    "This website technically has GPC compliance because": "Ce site Web est techniquement conforme au GPC car",
    "This website utilizes a known privacy-respecting framework that honors GPC globally.": "Ce site Web utilise un framework respectueux de la vie privée connu qui honore le GPC à l'échelle mondiale.",
    "This website was manually verified because of one of these reasons:": "Ce site Web a été vérifié manuellement pour l'une de ces raisons :",
    "This website's privacy policy states that it will respect GPC as an opt-out request.": "La politique de confidentialité de ce site Web stipule qu'il respectera le GPC en tant que demande d'opt-out.",
    "To automatically tell websites not to sell or share your data, go to the Privacy & Security settings page and turn on the Global Privacy Control (GPC) toggle.": "Pour indiquer automatiquement aux sites Web de ne pas vendre ou partager vos données, accédez à la page des paramètres Confidentialité et sécurité et activez le bouton Global Privacy Control (GPC).",
    "To comply with open-source and Creative Commons attribution requirements, we proudly acknowledge the following third-party materials used in Leef Browser:": "Pour nous conformer aux exigences d'attribution open source et Creative Commons, nous reconnaissons fièrement les matériels tiers suivants utilisés dans Leef Browser :",
    "Track your visits across other websites using tracking scripts and tracking cookies.": "Suivre vos visites sur d'autres sites Web à l'aide de scripts de suivi et de cookies de suivi.",
    "Tracking Protection": "Protection contre le pistage",
    "Translations": "Traductions",
    "Transparency & Funding": "Transparence & Financement",
    "Treat your visit as an active opt-out request under privacy regulations (like GDPR and CCPA).": "Traiter votre visite comme une demande d'opt-out active en vertu des réglementations sur la confidentialité (comme le RGPD et la CCPA).",
    "Typography & UI": "Typographie & UI",
    "Under GPC specifications, this website is legally bound to:": "Selon les spécifications GPC, ce site Web est légalement tenu de :",
