    "View detailed analytics and recent protection activity.": "Afficher les analyses détaillées et l'activité de protection récente.",
    "View Privacy Dashboard": "Voir le tableau de bord de confidentialité",
    "We believe your data belongs to you. Leef Browser does not collect analytics, telemetry, or browsing history. Everything stays local on your machine.": "Nous pensons que vos données vous appartiennent. Leef Browser ne collecte aucune donnée d'analyse, de télémétrie ou d'historique de navigation. Tout reste local sur votre machine.",
