    "Generate a local log file with system info to help us debug issues.": "Générer un fichier journal local avec les informations système pour nous aider à résoudre les problèmes.",
    "Generate Diagnostics Log": "Générer le journal de diagnostic",
    "<strong>Privacy Note:</strong> This file is saved locally to your Downloads folder. We do not collect telemetry. Unless you manually upload this file to the <a href=\"https://forms.gle/upGc1dvPYaoBw4o96\" target=\"_blank\" style=\"color: var(--primary-color); text-decoration: none;\">bug report form</a> or email it to <strong>contact.qtech@proton.me</strong>, no data leaves your device.": "<strong>Note de confidentialité :</strong> Ce fichier est enregistré localement dans votre dossier Téléchargements. Nous ne collectons pas de télémétrie. À moins que vous ne téléversiez manuellement ce fichier dans le <a href=\"https://forms.gle/upGc1dvPYaoBw4o96\" target=\"_blank\" style=\"color: var(--primary-color); text-decoration: none;\">formulaire de rapport de bug</a> ou que vous ne l'envoyiez par e-mail à <strong>contact.qtech@proton.me</strong>, aucune donnée ne quitte votre appareil.",
