    "Leef Labs Privacy Analytics is built to give you transparency. Everything shown here is stored 100% locally on your machine.": "Leef Labs Privacy Analytics est conçu pour vous offrir de la transparence. Tout ce qui est affiché ici est stocké à 100 % localement sur votre machine.",
