    "⚠️ FACTORY RESET: This will clear all settings, labs, history, and bookmarks. The browser will then relaunch. Proceed?": "⚠️ RÉINITIALISATION : Cela effacera tous les paramètres, les labs, l'historique et les favoris. Le navigateur va redémarrer. Continuer ?",
    "Diagnostics log generated! This file contains your settings and system info, but NO history or passwords. \n\nWould you like to open the bug report form now to upload it?": "Journal de diagnostic généré ! Ce fichier contient vos paramètres et infos système, mais AUCUN historique ni mot de passe. \n\nSouhaitez-vous ouvrir le formulaire de rapport de bug pour le téléverser ?",
    "Generating a bug report will save a diagnostics file to your PC.\n\nThis file contains system specs and configurations to help with bug reports. It will NEVER leave your PC unless you manually choose to share it.\n\nDo you want to proceed and generate the Bug Report log?": "La création d'un rapport de bug enregistrera un fichier de diagnostic sur votre PC.\n\nCe fichier contient les spécifications du système et configurations. Il ne quittera JAMAIS votre PC à moins que vous ne le partagiez manuellement.\n\nSouhaitez-vous continuer et générer le rapport ?",
