    "<strong>Privacy Note:</strong> This file is saved locally to your Downloads folder. We do not collect telemetry. Unless you manually upload this file to the <a href=\"https://forms.gle/upGc1dvPYaoBw4o96\" target=\"_blank\" style=\"color: var(--primary-color); text-decoration: none;\">bug report form</a> or email it to <strong>contact.qtech@proton.me</strong>, no data leaves your device.": "<strong>Privacyopmerking:</strong> Dit bestand wordt lokaal opgeslagen in uw map Downloads. We verzamelen geen telemetrie. Tenzij u dit bestand handmatig uploadt naar het <a href=\"https://forms.gle/upGc1dvPYaoBw4o96\" target=\"_blank\" style=\"color: var(--primary-color); text-decoration: none;\">foutmeldingsformulier</a> of het e-mailt naar <strong>contact.qtech@proton.me</strong>, verlaat er geen gegevens uw apparaat.",
