    "View Privacy Dashboard": "Privacydashboard bekijken",
    "What's New in Leef": "Wat is er nieuw in Leef",
    "<strong>Leef is a labor of love.</strong> We do not collect telemetry, we do not sell your data, and we do not make any money. We don't take donations. Enjoy using Leef exactly as it was intended: fast, private, and free.": "<strong>Leef is a labor of love.</strong> We do not collect telemetry, we do not sell your data, and we do not make any money. We don't take donations. Enjoy using Leef exactly as it was intended: fast, private, and free.",
    "<strong>Privacy Note:</strong> This file is saved locally to your Downloads folder. We do not collect telemetry. Unless you manually upload this file to the <a href=&quot;https://forms.gle/upGc1dvPYaoBw4o96&quot; target=&quot;_blank&quot; style=&quot;color: var(--primary-color); text-decoration: none;&quot;>bug report form</a> or email it to <strong>contact.qtech@proton.me</strong>, no data leaves your device.": "<strong>Privacy Note:</strong> This file is saved locally to your Downloads folder. We do not collect telemetry. Unless you manually upload this file to the <a href=&quot;https://forms.gle/upGc1dvPYaoBw4o96&quot; target=&quot;_blank&quot; style=&quot;color: var(--primary-color); text-decoration: none;&quot;>bug report form</a> or email it to <strong>contact.qtech@proton.me</strong>, no data leaves your device.",
