    "Even though they have stated that they respect GPC signals, this website may still use your data internally for analytics, data retention, internal research, and more. Read the privacy policy of this site for more info.": "Even though they have stated that they respect GPC signals, this website may still use your data internally for analytics, data retention, internal research, and more. Read the privacy policy of this site for more info.",
    "Finish": "Finish",
    "Force Google Search to show the ": "Force Google Search to show the ",
    "GPC is a legal browser signal that automatically tells websites you want to opt-out of having your personal data sold or shared. Under laws like California's CCPA and Europe's GDPR, participating websites are legally required to respect this signal.": "GPC is een wettelijk browsersignaal dat websites automatisch laat weten dat u bezwaar maakt tegen de verkoop of het delen van uw persoonsgegevens. Volgens wetten zoals de CCPA in Californië en de AVG/GDPR in Europa zijn deelnemende websites wettelijk verplicht dit signaal te respecteren.",
    "Global Privacy Control (GPC) is unsupported on this website.": "Global Privacy Control (GPC) is unsupported on this website.",
    "Great news! Leef successfully verified this site's GPC compliance declaration. The site officially respects the GPC signal.": "Great news! Leef successfully verified this site's GPC compliance declaration. The site officially respects the GPC signal.",
    "However, there is no hard evidence that they strictly comply, or they may not legally have to comply depending on where the company is based.": "However, there is no hard evidence that they strictly comply, or they may not legally have to comply depending on where the company is based.",
    "Ignore your explicit request to opt-out of personal data collection.": "Ignore your explicit request to opt-out of personal data collection.",
    "It has been audited by Leef and is confirmed to comply with the GPC standards.": "It has been audited by Leef and is confirmed to comply with the GPC standards.",
    "Its privacy policy states that they comply with GPC.": "Its privacy policy states that they comply with GPC.",
    "Learn More": "Learn More",
    "Leef Browser is dedicated to the public domain under the <strong>CC0 1.0</strong> license. You are free to copy, modify, and distribute this software for any purpose without restriction.": "Leef Browser is dedicated to the public domain under the <strong>CC0 1.0</strong> license. You are free to copy, modify, and distribute this software for any purpose without restriction.",
    "Leef has transmitted your Global Privacy Control preference to this site. We are currently checking the site's official compliance declaration (<code>/.well-known/gpc.json</code>) to verify if they respect the signal.": "Leef has transmitted your Global Privacy Control preference to this site. We are currently checking the site's official compliance declaration (<code>/.well-known/gpc.json</code>) to verify if they respect the signal.",
    "Leef is a fast, lightweight, and privacy-focused web browser built with Electron.<br>Designed for clarity, efficiency, and full local user control.": "Leef is a fast, lightweight, and privacy-focused web browser built with Electron.<br>Designed for clarity, efficiency, and full local user control.",
    "Leef is built for you. We don": "Leef is built for you. We don",
    "Leef sent the GPC signal to this site, but the site did not respond with a valid compliance document (<code>/.well-known/gpc.json</code>). It is highly likely the site does not recognize or support the GPC signal.": "Leef sent the GPC signal to this site, but the site did not respond with a valid compliance document (<code>/.well-known/gpc.json</code>). It is highly likely the site does not recognize or support the GPC signal.",
