    "Since the site does not declare GPC compliance, it may continue to collect, share, or sell your personal information, search history, and browser settings without respect to your opt-out preference.": "Since the site does not declare GPC compliance, it may continue to collect, share, or sell your personal information, search history, and browser settings without respect to your opt-out preference.",
    "Stop news from loading automatically. News only fetches when you click &quot;Refresh&quot;.": "Stop news from loading automatically. News only fetches when you click &quot;Refresh&quot;.",
