    "per second": "per seconde",
    "Page Load Failed": "Pagina laden mislukt",
    "⚠️ FACTORY RESET: This will clear all settings, labs, history, and bookmarks. The browser will then relaunch. Proceed?": "⚠️ FABRIEKSRESET: Dit wist alle instellingen, labs, geschiedenis en bladwijzers. De browser wordt daarna herstart. Doorgaan?",
    "Diagnostics log generated! This file contains your settings and system info, but NO history or passwords. \n\nWould you like to open the bug report form now to upload it?": "Diagnoselogboek gegenereerd! Dit bestand bevat instellingen en systeeminformatie, maar GEEN geschiedenis of wachtwoorden. \n\nWil je het foutrapportformulier nu openen om het te uploaden?",
    "Generating a bug report will save a diagnostics file to your PC.\n\nThis file contains system specs and configurations to help with bug reports. It will NEVER leave your PC unless you manually choose to share it.\n\nDo you want to proceed and generate the Bug Report log?": "Het genereren van een foutrapport slaat een diagnosebestand op op je pc.\n\nDit bestand bevat systeemspecificaties en configuraties om fouten op te lossen. Het verlaat NOOIT je pc tenzij je het handmatig deelt.\n\nWil je doorgaan en het foutrapportlogboek genereren?",
    "Enter the origin URL (e.g., https://discord.com):": "Voer de oorspronkelijke URL in (bijv. https://discord.com):",
    "Generating...": "Genereren...",
    "Starting Download...": "Downloaden starten...",
    "Checking...": "Controleren...",
    "Open Labs": "Labs openen",
    "Learn Why": "Meer informatie",
    "Check Archive": "Archief controleren",
    "View Diagnostic Report": "Diagnoserapport bekijken",
    "No downloads yet": "Nog geen downloads",
    "Windows Hello / Security Key": "Windows Hello / Beveiligingssleutel",
    "No trackers detected yet.": "Nog geen trackers gedetecteerd.",
    "Streaming above 1440p on YouTube may slow down Leef. For the best experience, keep quality at 1440p or below.": "Streamen boven 1440p op YouTube kan Leef vertragen. Voor de beste ervaring houdt u de weergavekwaliteit op 1440p of lager.",
    "Google recently removed its built-in dictionary card and replaced it with AI answers. Because Leef blocks AI-generated content by default, you would have no way to look up word definitions.": "Google heeft onlangs de ingebouwde woordenboekkaart vervangen door AI-antwoorden. Omdat Leef AI-inhoud standaard blokkeert, zou u geen definities meer kunnen opzoeken.",
    "You can turn this off any time in Leef &rarr; Settings &rarr; Browsing.": "U kunt dit op elk moment uitschakelen via Leef &rarr; Instellingen &rarr; Browsen.",
    "Search Engine Safe Mode": "Veilige modus voor zoekmachines",
    "Google recently changed its search engine backend to prioritize its \"AI Overview\" features. Because Leef injects specialized filters to strip out these AI components, the complex scripts served by Google can conflict with our blocker, causing the underlying Chromium layout engine to crash.": "Google heeft onlangs zijn backend aangepast om AI-overzichten voorrang te geven. Omdat Leef filters toepast om AI te verwijderen, kunnen scripts van Google botsen met onze blocker en Chromium laten crashen.",
    "To keep your browsing seamless and avoid infinite crash loops, Leef automatically loads your query in Safe Mode using DuckDuckGo.": "Om uw surfervaring soepel te houden en crashlussen te voorkomen, laadt Leef uw zoekopdracht automatisch in de veilige modus via DuckDuckGo.",
    "Detected Signal": "Gedetecteerd signaal",
    "Category": "Categorie",
    "AI models are trained on professional human data. High-quality human writing (academic, corporate, or journalistic) often flags as \"synthetic\" because it follows similar patterns of clarity and structure.": "AI-modellen zijn getraind op professionele menselijke teksten. Schrijfwerk van hoge kwaliteit wordt vaak gemarkeerd als \"synthetisch\" omdat het vergelijkbare heldere structuren vertoont.",
    "Confidence: {level}": "Betrouwbaarheid: {level}",
    "Linguistic Marker": "Linguïstische indicator",
    "Structural Pattern": "Structureel patroon",
    "Formatting Signature": "Opmaakhandtekening",
    "Found {count} linguistic markers.": "{count} linguïstische indicatoren gevonden.",
    "No synthetic patterns found.": "Geen synthetische patronen gevonden.",
